"""Derive current browser checks from the unchanged prior15 checks plus explicit scFates coverage."""
from pathlib import Path
from setup_deseq2_reference import ROOT

EXTRA=r'''
 await page.setViewportSize({width:1440,height:1000});await page.goto('http://127.0.0.1:8768/literature-review.html');await page.evaluate(()=>document.documentElement.dataset.theme='light');await page.locator('#tools-tab').click();await page.locator('#query').fill('scFates');const sf=page.locator('#results article').filter({has:page.getByRole('heading',{name:/^scFates \(/i})});assert.equal(await sf.count(),1);const st=(await sf.innerText()).toLowerCase();for(const term of ['ScfatesWorkflowCli','1.2.5','1.1.7','pseudotime','float64','upstream','R/GAM','83789804'])assert(st.includes(term.toLowerCase()),term);await sf.screenshot({path:path.join(out,'scfates-card-desktop.png'),style:'header{visibility:hidden!important}'});checks.push('scFates card exposes the validated original CPU tree/root/pseudotime workflow and scientific boundaries');
 const srow=JSON.parse(fs.readFileSync(path.join(root,'docs/literature/omics-2023-2026/tool-inventory.json'))).find(t=>t.id==='scfates');const sp=JSON.parse(fs.readFileSync(path.join(root,'docs/literature/scfates-workflow-development/VALIDATION.json')));assert.equal(srow.implementation_status,'upstream-adapter-validated');assert.equal(srow.development_candidate,sp.artifact.path);assert.equal(srow.development_candidate_sha256,sp.artifact.sha256);assert.equal(srow.development_cli_class,'org.jlinalg.cli.ScfatesWorkflowCli');assert.equal(srow.runtime_setup_cli_class,'org.jlinalg.cli.ScfatesSetupCli');assert.equal(srow.analysis_installs_software,false);assert.equal(srow.canonical_adapter_available,false);assert.equal(srow.independent_trajectory_refit,false);checks.push('scFates points to the exact validated artifact and standalone setup/analysis entry points');
 const p94=papers.find(p=>p.paper_id==='P094');await page.locator('#papers-tab').click();await page.locator('#query').fill(p94.doi);assert.equal(await page.locator('#results article').count(),1);const ptxt=clean(await page.locator('#P094').textContent());const srole=JSON.parse(fs.readFileSync(path.join(root,'tools/literature/reviewed-uses.json'))).reviews.find(r=>r.pmcid===p94.pmcid&&r.tool_id==='scfates');assert(ptxt.includes(clean(srole.use_summary)));assert(ptxt.includes(clean(srole.implementation_scope_note)));checks.push('P094 retains its exact original scFates role and unreported-edition/parameter distinctions');
 await page.goto('http://127.0.0.1:8768/literature-warnings.html');const sa=page.locator('#scfates-required-actions');assert(await sa.isVisible());const sat=(await sa.innerText()).toLowerCase();for(const term of ['SKIP3','FAIL2','earlier completed cases','RUN installs nothing','--allow-install','--allow-download','NEW paths','original-error.traceback','IndexError','NaN/Inf','no epsilon','scalar','initialization','NumPy','hard OS'])assert(sat.includes(term.toLowerCase()),term);await sa.screenshot({path:path.join(out,'scfates-actions-desktop.png'),style:'header{visibility:hidden!important}'});checks.push('scFates warnings prominently explain permitted setup, skip/failure recovery and source nonfinite/rounding/projection behavior');
 await page.setViewportSize({width:390,height:1000});await page.evaluate(()=>document.documentElement.dataset.theme='dark');assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await sa.screenshot({path:path.join(out,'scfates-actions-mobile-dark.png'),style:'header{visibility:hidden!important}'});assert.equal(errors.length,0,errors.join('\n'));checks.push('scFates dark warnings fit390px without horizontal overflow or browser errors');
 const currentWarning=clean(await page.locator('#palantir-required-actions').textContent());assert(currentWarning.includes('scFates CPU coordinate workflow is available'));assert(!currentWarning.includes('scFates, SAW, Stereopy and DoRothEA remain missing'));checks.push('current Palantir warnings point to available scFates while retaining the other missing tools');
'''

def generated():
    tools=ROOT/'tools/literature';old=(tools/'check_palantir_review_ui.cjs').read_text(encoding='utf8');text=old
    for a,b in [("['scFates','SAW','Stereopy','DoRothEA']","['SAW','Stereopy','DoRothEA']"),('the four newly registered tree/spatial/resource tools remain missing','the three other newly registered spatial/resource tools remain missing'),("['upstream-adapter-validated',69],['missing',255]","['upstream-adapter-validated',70],['missing',254]"),('400 cataloged tools,86 new integrations,255 missing','400 cataloged tools,87 new integrations,254 missing'),('palantir-ui-verification.json','scfates-ui-verification.json'),('Passed15 focused current CellPhoneDB and Palantir browser checks','Passed21 focused current CellPhoneDB, Palantir and scFates browser checks')]:assert text.count(a)==1,a;text=text.replace(a,b)
    marker=' const inventory=JSON.parse';assert text.count(marker)==1;text=text.replace(marker,EXTRA+marker);wrapper=(tools/'validate_palantir_catalog_ui.py').read_text(encoding='utf8').replace('palantir','scfates');return {tools/'check_scfates_review_ui.cjs':text.encode(),tools/'validate_scfates_catalog_ui.py':wrapper.encode()}

def verify():
    for path,raw in generated().items():assert path.read_bytes()==raw,'Current focused UI derivation differs: '+str(path)

if __name__=='__main__':
    for path,raw in generated().items():
        if path.exists():assert path.read_bytes()==raw
        else:path.write_bytes(raw)
    verify();print('Prepared299 unchanged general assertions and21 current focused checks; prior15-source file unchanged')
